export const { LockScroll } = Ui.Menu;
export const { UnlockScroll } = Ui.Menu;
export const { InertOthers } = Ui.Menu;
export const { RestoreInert } = Ui.Menu;
export const { FocusItems } = Ui.Menu;
export const { FocusButton } = Ui.Menu;
export const { ScrollIntoView } = Ui.Menu;
export const { ClickItem } = Ui.Menu;
export const { DelayClearSearch } = Ui.Menu;
export const { DetectMovementOrAnimationEnd } = Ui.Menu;
export const { AnchorMenu } = Ui.Menu;
export const { PortalMenuBackdrop } = Ui.Menu;

export type ItemConfig = Ui.Menu.ItemConfig;
export type GroupHeading = Ui.Menu.GroupHeading;
export type ViewInputs<Item extends string> = Ui.Menu.ViewInputs<Item>;
export type AnchorConfig = Ui.Menu.AnchorConfig;

export const init = (config: InitConfig): InitReturn => [
  Ui.Menu.init(config),
  [],
];

export const { create } = Ui.Menu;

export {
  animatedItemsClassName,
  backdropClassName,
  defaultAnchor,
  defaultItemsClassName,
  itemClassName,
  rootClassName,
  triggerClassName,
} from "./view";

export const triggerClassName =
  "inline-flex items-center justify-center rounded-lg border border-gray-300 bg-white px-4 py-2 text-base font-normal text-gray-900 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 disabled:cursor-not-allowed disabled:opacity-50";

export const rootClassName = "relative inline-block";

export const defaultItemsClassName =
  "absolute z-10 mt-1 w-48 overflow-hidden rounded-lg border border-gray-200 bg-white shadow-lg outline-none";

export const animatedItemsClassName =
  "absolute z-10 mt-1 w-48 overflow-hidden rounded-lg border border-gray-200 bg-white shadow-lg outline-none transition duration-150 ease-out data-[closed]:scale-95 data-[closed]:opacity-0";

export const itemClassName =
  "px-3 py-2 text-base text-gray-700 cursor-pointer data-[active]:bg-gray-100 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const backdropClassName = "fixed inset-0 z-0";

export const defaultAnchor = {
  placement: "bottom-start" as const,
  gap: 4,
  padding: 8,
};

import { Option } from "effect";
import { describe, expect, test } from "vitest";

import * as Menu from "./index";

type Action = "Edit" | "Duplicate" | "Delete";

const ActionMenu = Menu.create<Action>();
const menuId = "account-menu";

const initModel = (): Menu.Model => Menu.init({ id: menuId })[0];

const FocusAccountItems = Menu.FocusItems({ id: menuId });
const FocusAccountButton = Menu.FocusButton({ id: menuId });

const expectSomeOutMessage = (
  maybeOutMessage: Option.Option<Menu.OutMessage<Action>>,
  value: Action,
  index: number
) => {
  expect(Option.isSome(maybeOutMessage)).toBe(true);

  if (Option.isSome(maybeOutMessage)) {
    expect(maybeOutMessage.value).toEqual(Menu.Selected({ value, index }));
  }
};

describe("Menu registry component", () => {
  describe(Menu.init, () => {
    test("returns a model with no startup commands", () => {
      const [model, commands] = Menu.init({ id: menuId });

      expect(model.id).toBe(menuId);
      expect(model.isOpen).toBe(false);
      expect(model.isAnimated).toBe(false);
      expect(model.isModal).toBe(false);
      expect(commands).toEqual([]);
    });

    test("preserves animation and modal configuration", () => {
      const [model, commands] = Menu.init({
        id: menuId,
        isAnimated: true,
        isModal: true,
      });

      expect(model.isAnimated).toBe(true);
      expect(model.isModal).toBe(true);
      expect(commands).toEqual([]);
    });
  });

  describe("helper API", () => {
    test("open delegates to Opened behavior", () => {
      const [model, commands, maybeOutMessage] = ActionMenu.open(initModel());

      expect(model.isOpen).toBe(true);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusAccountItems.name);
      expect(commands[0]?.args).toEqual(FocusAccountItems.args);
      expect(Option.isNone(maybeOutMessage)).toBe(true);
    });

    test("close delegates to Closed behavior", () => {
      const [openModel] = ActionMenu.open(initModel());
      const [model, commands, maybeOutMessage] = ActionMenu.close(openModel);

      expect(model.isOpen).toBe(false);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusAccountButton.name);
      expect(commands[0]?.args).toEqual(FocusAccountButton.args);
      expect(Option.isNone(maybeOutMessage)).toBe(true);
    });

    test("selectItem closes and emits a typed Selected out-message", () => {
      const [openModel] = ActionMenu.open(initModel());
      const [model, commands, maybeOutMessage] = ActionMenu.selectItem(
        openModel,
        "Delete",
        2
      );

      expect(model.isOpen).toBe(false);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(FocusAccountButton.name);
      expectSomeOutMessage(maybeOutMessage, "Delete", 2);
    });

    test("modal open and close include scroll and inert commands", () => {
      const [closedModel] = Menu.init({
        id: menuId,
        isModal: true,
      });
      const [openModel, openCommands] = ActionMenu.open(closedModel);
      const [, closeCommands] = ActionMenu.close(openModel);

      expect(openCommands.map((command) => command.name)).toEqual([
        Menu.LockScroll().name,
        Menu.InertOthers({ id: menuId }).name,
        Menu.FocusItems({ id: menuId }).name,
      ]);
      expect(closeCommands.map((command) => command.name)).toEqual([
        Menu.FocusButton({ id: menuId }).name,
        Menu.UnlockScroll().name,
        Menu.RestoreInert({ id: menuId }).name,
      ]);
    });
  });
});

import { Scene, Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { childAttributes, html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Menu from "./index";

type Action = "Edit" | "Duplicate" | "Delete";

const ActionMenu = Menu.create<Action>();
const menuId = "account-menu";
const actions: readonly Action[] = ["Edit", "Duplicate", "Delete"];
const anchor = Menu.defaultAnchor;

const [initialModel] = Menu.init({ id: menuId });
const [animatedModel] = Menu.init({ id: menuId, isAnimated: true });

const AnchorAccountMenu = Menu.AnchorMenu({
  buttonId: `${menuId}-button`,
  anchor,
});
const SettleItemsAnimation = Ui.Animation.WaitForAnimationSettled({
  id: `${menuId}-items`,
});

const toAnimationMessage = (message: Ui.Animation.Message) =>
  Menu.GotAnimationMessage({ message });

const resolveMenuMounts = () =>
  Scene.Mount.resolveAll(
    [Menu.PortalMenuBackdrop, Menu.CompletedPortalMenuBackdrop()],
    [AnchorAccountMenu, Menu.CompletedAnchorMenu()]
  );

const view = (model: Menu.Model): Html => {
  const h = html<Menu.Message>();

  return h.submodel({
    slotId: model.id,
    model,
    view: ActionMenu.view,
    viewInputs: {
      anchor,
      items: actions,
      itemToConfig: (item) => ({
        className: Menu.itemClassName,
        content: h.span([], [item]),
      }),
      buttonContent: h.span([], ["Open actions"]),
      buttonAttributes: childAttributes([h.Class(Menu.triggerClassName)]),
      itemsAttributes: childAttributes([h.Class(Menu.defaultItemsClassName)]),
      backdropAttributes: childAttributes([
        h.DataAttribute("testid", "menu-backdrop"),
        h.Class(Menu.backdropClassName),
      ]),
      attributes: childAttributes([h.Class(Menu.rootClassName)]),
    },
    toParentMessage: (message) => message,
  });
};

const animatedView = (model: Menu.Model): Html => {
  const h = html<Menu.Message>();

  return h.submodel({
    slotId: model.id,
    model,
    view: ActionMenu.view,
    viewInputs: {
      anchor,
      items: actions,
      itemToConfig: (item) => ({
        className: Menu.itemClassName,
        content: h.span([], [item]),
      }),
      buttonContent: h.span([], ["Open animated actions"]),
      buttonAttributes: childAttributes([h.Class(Menu.triggerClassName)]),
      itemsAttributes: childAttributes([h.Class(Menu.animatedItemsClassName)]),
      backdropAttributes: childAttributes([
        h.DataAttribute("testid", "menu-backdrop"),
        h.Class(Menu.backdropClassName),
      ]),
      attributes: childAttributes([h.Class(Menu.rootClassName)]),
    },
    toParentMessage: (message) => message,
  });
};

describe("Menu registry view", () => {
  test("opens menu items from the trigger", () => {
    Scene.scene(
      { update: ActionMenu.update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("button", { name: "Open actions" })).toExist(),
      Scene.expect(Scene.text("Edit")).not.toExist(),
      Scene.click(Scene.role("button", { name: "Open actions" })),
      Scene.Command.expectHas(Menu.FocusItems({ id: menuId })),
      Scene.Command.resolve(
        Menu.FocusItems({ id: menuId }),
        Menu.CompletedFocusItems()
      ),
      resolveMenuMounts(),
      Scene.expect(Scene.text("Edit")).toExist(),
      Scene.expect(Scene.text("Duplicate")).toExist(),
      Scene.expect(Scene.text("Delete")).toExist()
    );
  });

  test("closes through the backdrop", () => {
    Scene.scene(
      { update: ActionMenu.update, view },
      Scene.with(initialModel),
      Scene.click(Scene.role("button", { name: "Open actions" })),
      Scene.Command.resolve(
        Menu.FocusItems({ id: menuId }),
        Menu.CompletedFocusItems()
      ),
      resolveMenuMounts(),
      Scene.click(Scene.testId("menu-backdrop")),
      Scene.Command.expectHas(Menu.FocusButton({ id: menuId })),
      Scene.Command.resolve(
        Menu.FocusButton({ id: menuId }),
        Menu.CompletedFocusButton()
      ),
      Scene.Mount.expectEnded(Menu.PortalMenuBackdrop, AnchorAccountMenu),
      Scene.expect(Scene.text("Edit")).not.toExist()
    );
  });

  test("animated menu keeps items visible after animation settles", () => {
    Scene.scene(
      { update: ActionMenu.update, view: animatedView },
      Scene.with(animatedModel),
      Scene.click(Scene.role("button", { name: "Open animated actions" })),
      Scene.Command.expectHas(
        Menu.FocusItems({ id: menuId }),
        Ui.Animation.RequestFrame
      ),
      Scene.Command.resolve(
        Menu.FocusItems({ id: menuId }),
        Menu.CompletedFocusItems()
      ),
      Scene.Command.resolve(
        Ui.Animation.RequestFrame,
        Ui.Animation.AdvancedAnimationFrame(),
        toAnimationMessage
      ),
      resolveMenuMounts(),
      Scene.Command.resolve(
        SettleItemsAnimation,
        Ui.Animation.EndedAnimation(),
        toAnimationMessage
      ),
      Scene.expect(Scene.text("Edit")).toExist()
    );
  });
});
